def transform(grid):
    """Fill rectangular hollow objects according to their interior size.

    Demonstrated rule: 3x3 interior -> 7, other rectangular interiors -> 2.
    This applies to outline objects on the background, preserving outlines.
    """
    g = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    # Find hollow rectangular borders from the original input and fill their
    # enclosed areas. Skip candidate rectangles whose edges are background.
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == background:
                        continue
                    if not all(grid[r][c] == color
                               for r in (r0, r1)
                               for c in range(c0, c1 + 1)):
                        continue
                    if not all(grid[r][c] == color
                               for c in (c0, c1)
                               for r in range(r0, r1 + 1)):
                        continue
                    fill = 7 if (r1 - r0 - 1 == 3 and c1 - c0 - 1 == 3) else 2
                    for r in range(r0 + 1, r1):
                        for c in range(c0 + 1, c1):
                            g[r][c] = fill
    # A 3x3 outlined motif with a single background-colored center maps center to 7.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == background or grid[r + 1][c + 1] != background:
                continue
            if all(grid[r + dr][c + dc] == color for dr, dc in
                   ((0, 0), (0, 1), (0, 2), (1, 0), (1, 2),
                    (2, 0), (2, 1), (2, 2))):
                g[r + 1][c + 1] = 7
    return g
